"use client";

import type { RefObject } from "react";
import { useEffect, useEffectEvent } from "react";
import { caretRectInTextarea, detectTrigger } from "../lib/trigger-detect";
import type { TriggerConfig, TriggerMenuItemData } from "./use-trigger-menu";
import { isComposingKey, useTriggerMenu } from "./use-trigger-menu";

function replaceRange(element: HTMLTextAreaElement, start: number, end: number, text: string) {
  element.focus();
  element.setSelectionRange(start, end);
  // execCommand keeps caret, joins native undo, and fires real `input` event React can hear
  const inserted = document.execCommand("insertText", false, text);
  if (inserted) return;
  const next = element.value.slice(0, start) + text + element.value.slice(end);
  const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value")?.set;
  setter?.call(element, next);
  element.dispatchEvent(new Event("input", { bubbles: true }));
  const caret = start + text.length;
  element.setSelectionRange(caret, caret);
}

export function useTextareaTriggerMenu<Item extends TriggerMenuItemData>(
  ref: RefObject<HTMLTextAreaElement | null>,
  options: { triggers: readonly TriggerConfig<Item>[] },
) {
  const controller = useTriggerMenu<Item>({
    triggers: options.triggers,
    onCommit: (item, trigger, match) => {
      const element = ref.current;
      if (!element) return;
      const mode = trigger.insert ?? "replace";
      const text = mode === "none" ? "" : (trigger.insertText?.(item) ?? `${trigger.char}${item.label} `);
      replaceRange(element, match.start, match.end, text);
      trigger.onSelect?.(item, { char: trigger.char, query: match.query });
    },
  });

  const syncTrigger = useEffectEvent(() => {
    const element = ref.current;
    if (!element) return;
    const caret = element.selectionStart ?? element.value.length;
    const chars = options.triggers.map((trigger) => trigger.char);
    const match = detectTrigger(element.value.slice(0, caret), chars);
    controller.report(match, match === null ? null : caretRectInTextarea(element, match.start));
  });

  const handleKeyDown = useEffectEvent((event: KeyboardEvent) => {
    if (isComposingKey(event)) return;
    if (controller.open && controller.handleKeyDown(event.key)) event.preventDefault();
  });

  const closeAfterBlur = useEffectEvent(() => {
    controller.close();
  });

  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    function onKeyDown(event: KeyboardEvent) {
      handleKeyDown(event);
    }
    function syncAfterInput() {
      // React must commit the controlled value before menu updates can render it.
      window.setTimeout(syncTrigger, 0);
    }
    function onBlur() {
      window.setTimeout(closeAfterBlur, 120);
    }

    element.addEventListener("input", syncAfterInput);
    element.addEventListener("keydown", onKeyDown);
    element.addEventListener("keyup", syncTrigger);
    element.addEventListener("click", syncTrigger);
    element.addEventListener("blur", onBlur);
    return () => {
      element.removeEventListener("input", syncAfterInput);
      element.removeEventListener("keydown", onKeyDown);
      element.removeEventListener("keyup", syncTrigger);
      element.removeEventListener("click", syncTrigger);
      element.removeEventListener("blur", onBlur);
    };
  }, [ref]);

  return controller;
}

import type { ReactNode } from "react";
import { useId, useReducer, useRef } from "react";
import type { TriggerMatch } from "../lib/trigger-detect";

export type TriggerMenuItemData = {
  id: string;
  label: string;
  description?: string;
  icon?: ReactNode;
  keywords?: readonly string[];
  disabled?: boolean;
  kind?: string;
  image?: string;
};

export type TriggerSelectContext = { char: string; query: string };

export type TriggerConfig<Item extends TriggerMenuItemData = TriggerMenuItemData> = {
  char: string;
  items: readonly Item[] | ((query: string) => readonly Item[]);
  filter?: (item: Item, query: string) => boolean;
  insert?: "replace" | "none";
  insertText?: (item: Item) => string;
  onSelect?: (item: Item, ctx: TriggerSelectContext) => void;
};

// Never touches DOM or editor: binding feeds state through `report` and performs insertion through `onCommit`,
// which is what lets one popup serve plain <textarea> and ProseMirror editor unchanged.

export type UseTriggerMenuOptions<Item extends TriggerMenuItemData> = {
  triggers: readonly TriggerConfig<Item>[];
  // backend-specific mutation for chosen item — mention replace, slash-command, and so on
  onCommit: (item: Item, trigger: TriggerConfig<Item>, match: TriggerMatch) => void;
};

/**
 * Popup attributes for the element that keeps focus (textarea or editor) while the menu is up. It stays a
 * multiline textbox (a <textarea> can't take role="combobox"), so open state is conveyed by `aria-controls`.
 */
export type TriggerMenuInputAria = {
  "aria-autocomplete": "list";
  "aria-haspopup": "listbox";
  "aria-controls"?: string;
  "aria-activedescendant"?: string;
};

export type TriggerMenuController<Item extends TriggerMenuItemData> = {
  open: boolean;
  items: readonly Item[];
  activeIndex: number;
  anchorRect: DOMRect | null;
  activeChar: string | null;
  query: string;
  /** Id for `TriggerMenuList`; the input's `aria-controls` points at it. */
  listId: string;
  /** Id for the option at `index`; the input's `aria-activedescendant` points at the active one. */
  optionId: (index: number) => string;
  inputAria: TriggerMenuInputAria;
  /** Binding → engine: publish current trigger match (or null) and caret rect to anchor to. */
  report: (match: TriggerMatch | null, anchorRect: DOMRect | null) => void;
  /** Binding → engine: route keydown while open. Returns true when engine consumed key. */
  handleKeyDown: (key: string) => boolean;
  /** View → engine. */
  setActiveIndex: (index: number) => void;
  select: (item: Item) => void;
  close: () => void;
  setOpen: (open: boolean) => void;
};

type DismissedMatch = { char: string; start: number; query: string };

export type TriggerMenuState = {
  open: boolean;
  char: string | null;
  query: string;
  anchorRect: DOMRect | null;
  activeIndex: number;
  dismissed: DismissedMatch | null;
};

export type TriggerMenuAction =
  | { type: "report"; match: TriggerMatch | null; anchorRect: DOMRect | null }
  | { type: "close"; dismissed: DismissedMatch | null }
  | { type: "move"; delta: number; count: number }
  | { type: "activate"; index: number };

export const CLOSED_TRIGGER_MENU: TriggerMenuState = {
  open: false,
  char: null,
  query: "",
  anchorRect: null,
  activeIndex: 0,
  dismissed: null,
};

/** A dismissed token stays closed until its query changes, so keyup/click re-detection after Escape can't reopen it. */
export function triggerMenuReducer(state: TriggerMenuState, action: TriggerMenuAction): TriggerMenuState {
  switch (action.type) {
    case "report": {
      const { match, anchorRect } = action;
      if (match === null) return { ...CLOSED_TRIGGER_MENU };
      const { dismissed } = state;
      if (dismissed !== null && dismissed.char === match.char && dismissed.start === match.start && dismissed.query === match.query) {
        return { ...CLOSED_TRIGGER_MENU, dismissed };
      }
      const activeIndex = state.open && state.char === match.char && state.query === match.query ? state.activeIndex : 0;
      return { open: true, char: match.char, query: match.query, anchorRect, activeIndex, dismissed: null };
    }
    case "close":
      return { ...CLOSED_TRIGGER_MENU, dismissed: action.dismissed };
    case "move":
      return {
        ...state,
        activeIndex: action.count === 0 ? 0 : (state.activeIndex + action.delta + action.count) % action.count,
      };
    case "activate":
      return { ...state, activeIndex: action.index };
  }
}

function matchesQuery(item: TriggerMenuItemData, query: string): boolean {
  if (query === "") return true;
  const needle = query.toLowerCase();
  if (item.label.toLowerCase().includes(needle)) return true;
  return (item.keywords ?? []).some((keyword) => keyword.toLowerCase().includes(needle));
}

function resolveItems<Item extends TriggerMenuItemData>(trigger: TriggerConfig<Item>, query: string): readonly Item[] {
  if (typeof trigger.items === "function") return trigger.items(query);
  const filter = trigger.filter ?? matchesQuery;
  return trigger.items.filter((item) => filter(item, query));
}

/** Keys an IME is still composing must never reach the menu or the composer's submit. */
export function isComposingKey(event: { isComposing: boolean; keyCode: number }): boolean {
  return event.isComposing || event.keyCode === 229;
}

export type TriggerMenuKeyIntent = "next" | "previous" | "commit" | "dismiss" | "pass";

/** What a key means to an open menu; an empty list passes Enter/Tab through so newline, submit and Tab-out still work. */
export function triggerMenuKeyIntent(key: string, open: boolean, itemCount: number): TriggerMenuKeyIntent {
  if (!open) return "pass";
  if (key === "ArrowDown") return "next";
  if (key === "ArrowUp") return "previous";
  if (key === "Escape") return "dismiss";
  if ((key === "Enter" || key === "Tab") && itemCount > 0) return "commit";
  return "pass";
}

export function useTriggerMenu<Item extends TriggerMenuItemData>({
  triggers,
  onCommit,
}: UseTriggerMenuOptions<Item>): TriggerMenuController<Item> {
  const [state, dispatch] = useReducer(triggerMenuReducer, CLOSED_TRIGGER_MENU);
  const lastMatch = useRef<TriggerMatch | null>(null);
  const listId = useId();

  const activeTrigger = state.char === null ? null : (triggers.find((trigger) => trigger.char === state.char) ?? null);
  const items = activeTrigger === null ? [] : resolveItems(activeTrigger, state.query);
  const optionId = (index: number) => `${listId}-option-${index}`;
  const hasActiveItem = state.open && state.activeIndex < items.length;

  function dismiss() {
    const match = lastMatch.current;
    lastMatch.current = null;
    dispatch({ type: "close", dismissed: match === null ? null : { char: match.char, start: match.start, query: match.query } });
  }

  function close() {
    lastMatch.current = null;
    dispatch({ type: "close", dismissed: null });
  }

  function select(item: Item) {
    const match = lastMatch.current;
    if (activeTrigger !== null && match !== null) onCommit(item, activeTrigger, match);
    close();
  }

  function report(match: TriggerMatch | null, anchorRect: DOMRect | null) {
    const known = match !== null && triggers.some((trigger) => trigger.char === match.char);
    lastMatch.current = known ? match : null;
    dispatch({ type: "report", match: known ? match : null, anchorRect });
  }

  function handleKeyDown(key: string): boolean {
    const intent = triggerMenuKeyIntent(key, state.open, items.length);
    if (intent === "next" || intent === "previous") {
      dispatch({ type: "move", delta: intent === "next" ? 1 : -1, count: items.length });
    } else if (intent === "commit") {
      const item = items[state.activeIndex];
      if (item && !item.disabled) select(item);
    } else if (intent === "dismiss") {
      dismiss();
    }
    return intent !== "pass";
  }

  function setOpen(open: boolean) {
    if (!open) dismiss();
  }

  function setActiveIndex(index: number) {
    dispatch({ type: "activate", index });
  }

  return {
    open: state.open,
    items,
    activeIndex: state.activeIndex,
    anchorRect: state.anchorRect,
    activeChar: state.char,
    query: state.query,
    listId,
    optionId,
    inputAria: {
      "aria-autocomplete": "list",
      "aria-haspopup": "listbox",
      "aria-controls": state.open ? listId : undefined,
      "aria-activedescendant": hasActiveItem ? optionId(state.activeIndex) : undefined,
    },
    report,
    handleKeyDown,
    setActiveIndex,
    select,
    close,
    setOpen,
  };
}

export type TriggerMatch = {
  /** trigger character that opened menu (e.g. "/" or "@"). */
  char: string;
  /** Text typed after trigger char, up to caret (never contains whitespace). */
  query: string;
  /** Offset of trigger char in scanned text; token spans [start, end). */
  start: number;
  /** Offset of caret in scanned text (exclusive end of trigger token). */
  end: number;
};

const WHITESPACE = /\s/u;

// only fires when char sits at start or after whitespace, so `path/to` never triggers on "/"
export function detectTrigger(textBeforeCaret: string, triggerChars: readonly string[]): TriggerMatch | null {
  const triggerSet = new Set(triggerChars);
  for (let i = textBeforeCaret.length - 1; i >= 0; i -= 1) {
    const char = textBeforeCaret.at(i);
    if (char === undefined) return null;
    if (WHITESPACE.test(char)) return null;
    if (triggerSet.has(char)) {
      const preceding = i === 0 ? "" : (textBeforeCaret.at(i - 1) ?? "");
      if (preceding === "" || WHITESPACE.test(preceding)) {
        return { char, query: textBeforeCaret.slice(i + 1), start: i, end: textBeforeCaret.length };
      }
      return null;
    }
  }
  return null;
}

// layout-affecting properties mirrored onto measuring div so its caret column matches textarea's
const MIRROR_PROPERTIES = [
  "direction",
  "writing-mode",
  "box-sizing",
  "width",
  "font-family",
  "font-size",
  "font-weight",
  "font-style",
  "font-variant",
  "letter-spacing",
  "word-spacing",
  "text-transform",
  "text-indent",
  "line-height",
  "tab-size",
  "padding-top",
  "padding-right",
  "padding-bottom",
  "padding-left",
  "border-top-width",
  "border-right-width",
  "border-bottom-width",
  "border-left-width",
];

// textarea exposes no caret geometry, so text is mirrored into off-screen div and marker's box is read at offset
export function caretRectInTextarea(element: HTMLTextAreaElement, offset: number): DOMRect {
  const doc = element.ownerDocument;
  const computed = doc.defaultView?.getComputedStyle(element);
  const mirror = doc.createElement("div");
  const style = mirror.style;
  style.position = "absolute";
  style.visibility = "hidden";
  style.whiteSpace = "pre-wrap";
  style.overflowWrap = "break-word";
  style.top = "0";
  style.left = "-9999px";
  if (computed) {
    for (const property of MIRROR_PROPERTIES) style.setProperty(property, computed.getPropertyValue(property));
  }

  mirror.textContent = element.value.slice(0, offset);
  const marker = doc.createElement("span");
  // must stay non-empty or it has no box at very end of text
  marker.textContent = element.value.slice(offset) || ".";
  mirror.appendChild(marker);
  doc.body.appendChild(mirror);

  const elementRect = element.getBoundingClientRect();
  const mirrorRect = mirror.getBoundingClientRect();
  const markerRect = marker.getBoundingClientRect();
  const lineHeight = computed ? Number.parseFloat(computed.lineHeight) : 0;
  const height = markerRect.height || (Number.isFinite(lineHeight) ? lineHeight : 16);
  const x = elementRect.left + (markerRect.left - mirrorRect.left) - element.scrollLeft;
  const y = elementRect.top + (markerRect.top - mirrorRect.top) - element.scrollTop;

  doc.body.removeChild(mirror);
  return new DOMRect(x, y, 1, height);
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="drawer"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="toast"][data-slot="title"]) {
    color: var(--cui-popup-title-foreground);
    font-size: var(--cui-popup-title-font-size);
    font-weight: var(--cui-popup-title-font-weight);
    line-height: var(--cui-popup-title-line-height);
    letter-spacing: var(--cui-popup-title-letter-spacing);
    text-wrap: balance;
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="drawer"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="toast"][data-slot="description"]) {
    color: var(--cui-popup-description-foreground);
    font-size: var(--text-body);
    text-wrap: pretty;
  }

  :where([data-control-family="popup"][data-slot="arrow"]) {
    color: var(--cui-popup-background);
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="top"]) {
    inset-block-end: -8px;
    rotate: 180deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="bottom"]) {
    inset-block-start: -8px;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="left"]) {
    right: -10px;
    rotate: 90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="right"]) {
    left: -10px;
    rotate: -90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-start"]) {
    inset-inline-end: -10px;
    rotate: 90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-end"]) {
    inset-inline-start: -10px;
    rotate: -90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-start"]:dir(rtl)) {
    rotate: -90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-end"]:dir(rtl)) {
    rotate: 90deg;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"]) {
    padding: calc(var(--spacing) * 1) calc(var(--spacing) * 2.5);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="content"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="content"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="content"]) {
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="header"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding: calc(var(--spacing) * 4) calc(var(--spacing) * 4) 0;
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="body"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="body"]) {
    gap: calc(var(--spacing) * 4);
    padding-inline: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="body"]:not(:has(~ [data-slot="footer"]))),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="body"]:not(:has(~ [data-slot="footer"]))) {
    padding-block-end: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="footer"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
    padding: 0 calc(var(--spacing) * 4) calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding-block-end: calc(var(--spacing) * 3);
  }

  :where([data-control-family="popup"][data-popup-kind="popover"][data-popup-part="surface"][data-padding="default"]),
  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-popup-part="surface"]) {
    padding: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="trigger"]:is(a)) {
    border-radius: var(--radius-sm);
    color: var(--foreground);
    font-weight: var(--font-weight-medium);
    text-decoration-line: underline;
    text-decoration-color: var(--border);
    text-decoration-thickness: 1px;
    text-underline-offset: 2px;
    cursor: pointer;
    transition: text-decoration-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="trigger"]:is(a)[data-popup-open]) {
    text-decoration-color: var(--foreground);
  }

  @media (hover: hover) {
    :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="trigger"]:is(a):hover) {
      text-decoration-color: var(--foreground);
    }
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="link"]) {
    text-decoration-line: none;
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"]) {
    text-align: start;
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-starting-style]),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-ending-style]) {
    opacity: 0;
  }

  :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]) {
    --_popup-button-root-close-opacity: 70%;
    opacity: var(--_popup-button-root-close-opacity);
  }

  :where(
    [data-control-family="popup"][data-surface="modal"] > [data-control-family="button"][data-popup-part="close"][data-icon-only="true"]
  ) {
    position: absolute;
    inset-block-start: var(--cui-popup-close-inset);
    inset-inline-end: var(--cui-popup-close-inset);
  }

  :where(
    [data-control-family="popup"][data-surface="modal"]:has(> [data-control-family="button"][data-popup-part="close"])
      [data-control-family="popup"][data-slot="header"]
  ) {
    padding-inline-end: calc(var(--cui-popup-close-inset) + var(--control-h-xs) + var(--spacing) * 2);
  }

  @media (hover: hover) {
    :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]:hover) {
      --_popup-button-root-close-opacity: 100%;
      opacity: var(--_popup-button-root-close-opacity);
    }
  }
}

@property --cui-popup-title-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-popup-title-font-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-title-font-weight {
  syntax: "<number>";
  inherits: true;
  initial-value: 400;
}

@property --cui-popup-title-line-height {
  syntax: "<number>";
  inherits: true;
  initial-value: 1.5;
}

@property --cui-popup-title-letter-spacing {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-description-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-popup-close-inset {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="model-switcher"][data-slot="hint"]) {
    margin-inline-start: auto;
    padding-inline-start: calc(var(--spacing) * 4);
    font-size: var(--text-micro);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="group-label"]) {
    padding-block: calc(var(--spacing) * 1) calc(var(--spacing) * 0.5);
    text-transform: uppercase;
    font-size: var(--text-micro);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    color: var(--muted-foreground);
  }

